class Finder {
    private static int calls = 0;

    public static int search(int[] a, int target, int lo, int hi) {
        calls++;
        if (lo > hi) {
            return -1;
        }
        int mid = (lo + hi) / 2;
        if (a[mid] == target) {
            return mid;
        }
        if (a[mid] < target) {
            return search(a, target, mid + 1, hi);
        }
        return search(a, target, lo, mid - 1);
    }

    public static int getCalls() {
        return calls;
    }
}

public class Client {
    public static void main(String[] args) {
        int[] a = { 8, 16, 17, 25, 33, 35, 49, 57 };
        int idx = Finder.search(a, 33, 0, a.length - 1);
        System.out.println(idx + " " + Finder.getCalls());
    }
}
```

